# Writes the lantern river's hedra command files and its water texture:
#   water.txt + textures/water.png, bank.txt (the far bank and a low near bank), hills.txt, tree.txt,
#   house.txt, jetty.txt, reeds.txt, moon.txt (moon + its glint on the water), stars.txt, shine.txt.
# Run from models/env: /usr/bin/python3 make_env.py. Up Z, front -Y (hedra): world x = hedra x,
# world z = -hedra y. Colours are exact Midnight Ablaze steps (sRGB 0..1).
import math, random
from PIL import Image

P = ["#130208", "#1f0510", "#31051e", "#460e2b", "#7c183c", "#d53c6a", "#ff8274"]
def rgb(h):
    h = h.lstrip("#")
    return tuple(int(h[i:i + 2], 16) / 255 for i in (0, 2, 4))
def col(i, emit=False):
    r, g, b = rgb(P[i])
    s = f"--base-color {r:.4f} {g:.4f} {b:.4f}"
    return s + (f" --emission {r:.4f} {g:.4f} {b:.4f}" if emit else "")
def write(name, lines):
    open(name, "w").write("\n".join(lines) + "\n")
def box(name, x, z, y, sx, sz, sy, mat, rot=None):
    """a box centred at world (x, y, z), sizes along world x, z, y"""
    L = [f"add mesh cube --name {name} --size 1 --location {x:.3f} {-z:.3f} {y:.3f}",
         f"scale {sx:.3f} {sz:.3f} {sy:.3f}", "apply --scale"]
    if rot:
        L += [f"set rotation {rot[0]} {rot[1]} {rot[2]}", "apply --rotation"]
    return L + [f"material assign {mat}"]

# ---------------------------------------------------------------- water + texture
random.seed(3)
TW, TH = 72, 48                                    # 18 x 12 m: 0.25 m a texel
img = Image.new("RGB", (TW, TH), tuple(int(c * 255) for c in rgb(P[2])))
px = img.load()
for _ in range(70):                                # ripple dashes, long across the stream
    x, y = random.randrange(TW), random.randrange(TH)
    c = P[3] if random.random() < 0.7 else P[1]
    for dx in range(random.choice((3, 4, 5, 6))):
        px[(x + dx) % TW, y] = tuple(int(v * 255) for v in rgb(c))
img.save("textures/water.png")
write("water.txt", [
    "# The river: an 18 x 12 m plane (world z -3.5..8.5), dark water with ripple dashes painted in a",
    "# palette-exact 72 x 48 texture. Generated by make_env.py. Up Z.", "new",
    "add mesh grid --name Water --size 1 --x-subdivisions 6 --y-subdivisions 4 --location 0 -2.5 0",
    "scale 18 12 1", "apply --scale",
    "material new Water --base-color 1 1 1", "material assign Water",
    "active Water", "mode edit", "select all", "uv project-from-view top --scale-to-bounds", "mode object",
    "material texture Water base-color textures/water.png", "shade flat", "export water.glb"])

# ---------------------------------------------------------------- banks
write("bank.txt", [
    "# The far bank: an earth slab x -9..9, world z -3..-7.5, top 0.4 m, its front face sloping into the",
    "# water, the top jittered a little. Generated by make_env.py. Up Z.", "new",
    f"material new Earth {col(2)} --no-slot", f"material new Grass {col(3)} --no-slot",
    "add mesh grid --name Bank --size 1 --x-subdivisions 12 --y-subdivisions 3 --location 0 5.25 0.4",
    "scale 18 4.5 1", "apply --scale", "material assign Grass",
    "mode edit", "select all", "randomize --amount 0.05 --seed 2", "mode object",
    "add mesh grid --name Slope --size 1 --x-subdivisions 12 --y-subdivisions 1 --location 0 3.0 0.2",
    "scale 18 0.6 1", "apply --scale", "set rotation -55 0 0", "apply --rotation", "material assign Earth",
    "select all", "shade flat", "export bank.glb"])

# ---------------------------------------------------------------- hills: a row of low faceted mounds
L = ["# Low hills behind the village: flattened, jittered icospheres along world z -8..-10. Up Z.", "new",
     f"material new Hill {col(1)} --no-slot"]
random.seed(7)
for i, (x, z, r, h) in enumerate([(-7.5, -9, 2.6, 1.3), (-3.6, -8.6, 2.4, 1.0), (0.4, -9.4, 3.0, 1.5),
                                   (4.4, -8.8, 2.3, 0.9), (7.8, -9.2, 2.8, 1.3)]):
    L += [f"add mesh ico-sphere --name H{i} --subdivisions 2 --radius 1 --location {x} {-z} 0",
          f"scale {r} 1.6 {h}", "apply --scale", "mode edit", "select all",
          f"randomize --amount 0.08 --seed {i + 1}", "select vert where \"pos.z < -0.05\"", "delete vert",
          "mode object", "material assign Hill"]
L += ["select all", "active H0", "join", "rename H0 Hills", "shade flat", "export hills.glb"]
write("hills.txt", L)

# ---------------------------------------------------------------- tree: a dark three-tier conifer
write("tree.txt", [
    "# A night conifer: a short trunk and three stacked 6-sided cones, 2.2 m tall. Up Z.", "new",
    f"material new Bark {col(2)} --no-slot", f"material new Needles {col(2)} --no-slot",
    "add mesh cylinder --name Trunk --vertices 6 --radius 0.1 --depth 0.5 --location 0 0 0.25", "material assign Bark",
    "add mesh cone --name C1 --vertices 6 --radius1 0.62 --radius2 0.1 --depth 0.9 --location 0 0 0.85", "material assign Needles",
    "add mesh cone --name C2 --vertices 6 --radius1 0.5 --radius2 0.06 --depth 0.8 --location 0 0 1.35", "material assign Needles",
    "add mesh cone --name C3 --vertices 6 --radius1 0.36 --radius2 0 --depth 0.75 --location 0 0 1.85", "material assign Needles",
    "select all", "shade flat", "export tree.glb"])

# ---------------------------------------------------------------- house: walls, a hipped roof, glowing windows
write("house.txt", [
    "# A riverside house: 1.6 x 1.2 x 1.0 m walls, a hipped roof with wide eaves, two glowing windows",
    "# on the front, one on the right side (standing 6 cm proud, 0.7 m apart so they stay apart as splats). Up Z, front -Y.", "new",
    f"material new Wall {col(3)} --no-slot", f"material new Roof {col(1)} --no-slot",
    f"material new Window {col(5, True)} --no-slot",
    *box("Walls", 0, 0, 0.5, 1.6, 1.2, 1.0, "Wall"),
    "add mesh cone --name Roof --vertices 4 --radius1 1.35 --radius2 0.25 --depth 0.7 --location 0 0 1.35 --rotation 0 0 45",
    "apply --rotation", "scale 1.0 0.75 1", "apply --scale", "material assign Roof",
    *box("W1", -0.48, 0.63, 0.55, 0.24, 0.06, 0.26, "Window"),
    *box("W2", 0.48, 0.63, 0.55, 0.24, 0.06, 0.26, "Window"),
    *box("W3", 0.83, 0.0, 0.55, 0.06, 0.26, 0.26, "Window"),
    "select all", "shade flat", "export house.glb"])

# ---------------------------------------------------------------- jetty: planks on posts into the water
L = ["# A small jetty: a 0.9 m wide plank deck 3 m long running from the far bank into the river, on",
     "# six posts, with a glowing lamp post at its end. Up Z, along world +z.", "new",
     f"material new Wood {col(3)} --no-slot", f"material new Post {col(2)} --no-slot",
     f"material new Lamp {col(6, True)} --no-slot"]
L += box("Deck", 0, 1.5, 0.45, 0.9, 3.0, 0.1, "Wood")
for i, z in enumerate((0.3, 1.5, 2.8)):
    for s in (-1, 1):
        L += box(f"P{i}{s + 1}", s * 0.38, z, 0.2, 0.12, 0.12, 0.65, "Post")
L += box("LampPost", 0.38, 2.9, 0.95, 0.1, 0.1, 1.0, "Post")
L += ["add mesh ico-sphere --name Lamp --subdivisions 1 --radius 0.13 --location 0.38 -2.9 1.5", "material assign Lamp"]
L += ["select all", "shade flat", "export jetty.glb"]
write("jetty.txt", L)

# ---------------------------------------------------------------- reeds: a clump of tilted blades
random.seed(11)
L = ["# A clump of reeds: nine thin tilted blades (4-sided cones), 0.6-1.1 m tall, two with seed heads. Up Z.",
     "new", f"material new Reed {col(1)} --no-slot", f"material new Head {col(2)} --no-slot"]
for i in range(9):
    x, y = random.uniform(-0.35, 0.35), random.uniform(-0.25, 0.25)
    h = random.uniform(0.6, 1.1)
    tx, ty = random.uniform(-14, 14), random.uniform(-10, 10)
    L += [f"add mesh cone --name R{i} --vertices 4 --radius1 0.06 --radius2 0 --depth {h:.2f} --location {x:.2f} {y:.2f} {h / 2:.2f}",
          f"set rotation {ty:.1f} {tx:.1f} 0", "material assign Reed"]
    if i % 4 == 0:
        L += [f"add mesh cube --name S{i} --size 1 --location {x + h * math.sin(math.radians(tx)) * 0.8:.2f} {y - h * math.sin(math.radians(ty)) * 0.8:.2f} {h * 0.85:.2f}",
              "scale 0.08 0.08 0.2", "apply --scale", f"set rotation {ty:.1f} {tx:.1f} 0", "material assign Head"]
L += ["select all", "shade flat", "export reeds.glb"]
write("reeds.txt", L)

# ---------------------------------------------------------------- moon (faces the camera), its glint on the water
write("moon.txt", [
    "# The moon: a crescent. A 12-sided disc r 0.6 and, 4 cm in front of it, a darker disc r 0.52 offset",
    "# up and right (the unlit side with a little earthshine). Upright, facing the camera (-Y in hedra). Up Z.", "new",
    f"material new Moon {col(5, True)} --no-slot", f"material new Shade {col(2)} --no-slot",
    "add mesh circle --name Moon --vertices 12 --radius 0.6 --cap-fill triangle-fan --location 0 0 0 --rotation 90 0 0",
    "apply --rotation", "material assign Moon",
    "add mesh circle --name Dark --vertices 12 --radius 0.52 --cap-fill triangle-fan --location 0.24 -0.04 0.14 --rotation 90 0 0",
    "apply --rotation", "material assign Shade",
    "select all", "shade flat", "export moon.glb"])
random.seed(5)
L = ["# The moon's glint on the water: flat dashes 4 cm above the river in a column, wider near the camera.",
     "# Up Z; the column runs along world +z from 0 to 7.", "new",
     f"material new Glint {col(5, True)} --no-slot", f"material new Glint2 {col(4, True)} --no-slot"]
for i in range(7):
    z = 0.3 + i * 0.9
    w = 0.5 + z * 0.15 + random.uniform(-0.1, 0.2)
    x = random.uniform(-0.25, 0.25)
    L += box(f"G{i}", x, z, 0.03, w, 0.16, 0.03, "Glint" if i % 2 else "Glint2")
L += ["select all", "shade flat", "export glint.glb"]
write("glint.txt", L)

# ---------------------------------------------------------------- stars on a far backdrop
random.seed(9)
L = ["# Stars: small cubes scattered over a band x -7..7, height 0.7..3.9 m, all at world z -16 (far behind",
     "# the hills; the camera's pitch lifts them into the sky). Unlit, single art pixels. Up Z.", "new",
     f"material new Star {col(4, True)} --no-slot", f"material new Bright {col(5, True)} --no-slot"]
for i in range(46):
    x, h = random.uniform(-7.0, 7.0), random.uniform(0.7, 3.9)
    s = 0.05 if i % 6 else 0.08
    L += box(f"S{i}", x, -16 + random.uniform(-0.5, 0.5), h, s, s, s, "Bright" if i % 6 == 0 else "Star")
L += ["select all", "shade flat", "export stars.glb"]
write("stars.txt", L)

# ---------------------------------------------------------------- shine: a lit lantern's light on the water
write("shine.txt", [
    "# A lit lantern's light on the water: three flat dashes, 4 cm above the river. A game bone pool. Up Z.", "new",
    f"material new Shine {col(5, True)} --no-slot",
    *box("A", 0, 0, 0.04, 0.7, 0.14, 0.03, "Shine"),
    *box("B", 0.1, 0.35, 0.04, 0.45, 0.14, 0.03, "Shine"),
    *box("C", -0.08, -0.32, 0.04, 0.4, 0.12, 0.03, "Shine"),
    "select all", "active A", "join", "rename A Shine", "shade flat", "export shine.glb"])
print("wrote water, bank, hills, tree, house, jetty, reeds, moon, glint, stars, shine")
